import { announce, createChange, definePrimitive, type ChangeDetails } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

type ConfirmButtonArmedChangeReason =
  | "trigger-press"
  | "timeout"
  | "escape-key"
  | "focus-out"
  | "confirm"
  | "imperative"

/** What confirmed: a second press, a hold, or a call (an agent, a controller). */
type ConfirmButtonConfirmReason = "trigger-press" | "hold" | "imperative"

type ConfirmButtonOptions = {
  armed?: boolean
  defaultArmed?: boolean
  onArmedChange?: (armed: boolean, details: ChangeDetails<ConfirmButtonArmedChangeReason>) => void
  /** Runs the action. Return a Promise to mark the button pending until it settles. */
  onConfirm?: (details: { reason: ConfirmButtonConfirmReason; event?: Event }) => unknown
  /** How long the button stays armed, in milliseconds; 0 keeps it armed until it confirms or disarms otherwise. */
  timeout?: number
  /** Holding a pointer, Enter or Space this long confirms, in milliseconds. A second press always works too. */
  hold?: number
  disabled?: boolean
  /** Read politely once the button arms, so a screen reader hears that the next press confirms. */
  armedAnnouncement?: string
}

const defaultTimeout = 4000

function isThenable(value: unknown): value is PromiseLike<unknown> {
  return typeof value === "object" && value !== null && "then" in value && typeof value.then === "function"
}

const confirmButton = definePrimitive({
  name: "confirm-button",
  options: {
    armed: "boolean",
    defaultArmed: "boolean",
    onArmedChange: "callback",
    onConfirm: "action",
    timeout: "number",
    hold: "number",
    disabled: "boolean",
    armedAnnouncement: "string",
  },
  controlled: ["armed"],
  state: (options: ConfirmButtonOptions) => ({
    armed: options.armed ?? options.defaultArmed ?? false,
    pending: false,
    holding: false,
    disabled: options.disabled ?? false,
  }),
  sync: (options) => ({
    ...(options.armed === undefined ? {} : { armed: options.armed }),
    disabled: options.disabled ?? false,
  }),
  api: (context) => {
    const change = createChange(context)
    let disarmTimer: ReturnType<typeof setTimeout> | undefined
    let holdTimer: ReturnType<typeof setTimeout> | undefined
    let swallowReleaseClickAfterHold = false

    const stopHold = () => {
      clearTimeout(holdTimer)
      holdTimer = undefined
      if (context.store.get().holding) context.store.set({ holding: false })
    }
    context.onDestroy(() => {
      clearTimeout(disarmTimer)
      clearTimeout(holdTimer)
    })

    const blocked = () => {
      const state = context.store.get()
      return state.disabled || state.pending
    }

    const api = {
      arm(event?: Event) {
        if (blocked() || context.store.get().armed) return false
        if (!change("armed", true, { reason: "trigger-press", event })) return false
        const { timeout = defaultTimeout, armedAnnouncement } = context.options()
        clearTimeout(disarmTimer)
        if (timeout > 0) disarmTimer = setTimeout(() => api.disarm("timeout"), timeout)
        if (armedAnnouncement) announce(armedAnnouncement)
        return true
      },
      disarm(reason: ConfirmButtonArmedChangeReason = "imperative", event?: Event) {
        clearTimeout(disarmTimer)
        if (!context.store.get().armed) return false
        return change("armed", false, { reason, event })
      },
      /** Runs `onConfirm` at once, armed or not; for an agent it waits for the person through `allow`. */
      confirm(event?: Event, reason: ConfirmButtonConfirmReason = "imperative") {
        if (blocked()) {
          const why = context.store.get().disabled ? "disabled" : "its confirmation runs"
          return unavailable("confirm", `isn't available while ${why}`, { reason, event })
        }
        stopHold()
        api.disarm("confirm", event)
        const result = context.options().onConfirm?.({ reason, event })
        if (isThenable(result)) {
          context.store.set({ pending: true })
          const settle = () => context.store.set({ pending: false })
          result.then(settle, settle)
        }
        return true
      },
      /** The first press arms, the second confirms. */
      press(event?: Event) {
        if (swallowReleaseClickAfterHold) {
          swallowReleaseClickAfterHold = false
          return false
        }
        return context.store.get().armed ? api.confirm(event, "trigger-press") : api.arm(event)
      },
      startHold(event?: Event) {
        swallowReleaseClickAfterHold = false
        const { hold } = context.options()
        if (!hold || blocked() || holdTimer !== undefined) return false
        context.store.set({ holding: true })
        holdTimer = setTimeout(() => {
          holdTimer = undefined
          swallowReleaseClickAfterHold = true
          api.confirm(event, "hold")
        }, hold)
        return true
      },
      endHold() {
        stopHold()
        if (swallowReleaseClickAfterHold)
          setTimeout(() => {
            swallowReleaseClickAfterHold = false
          }, 0)
      },
    }
    return api
  },
  slots: (slot) => ({
    root: slot<{}, { armed: boolean; pending: boolean; holding: boolean }>({
      role: "button",
      focus: "native",
      press: ({ api }, event) => api.press(event),
      state: (state) => ({ armed: state.armed, pending: state.pending, holding: state.holding }),
      attrs: (state) => ({
        type: "button",
        disabled: state.disabled ? "" : undefined,
        "aria-busy": state.pending ? "true" : undefined,
        "data-armed": state.armed ? "" : undefined,
        "data-holding": state.holding ? "" : undefined,
        "data-pending": state.pending ? "" : undefined,
        "data-disabled": state.disabled ? "" : undefined,
      }),
      on: {
        keydown: (event, { api, store }) => {
          const keyboard = event as KeyboardEvent
          if (keyboard.key === "Escape" && store.get().armed) {
            keyboard.preventDefault()
            keyboard.stopPropagation()
            api.disarm("escape-key", keyboard)
          } else if ((keyboard.key === "Enter" || keyboard.key === " ") && !keyboard.repeat) {
            api.startHold(keyboard)
          }
        },
        keyup: (_event, { api }) => api.endHold(),
        pointerdown: (event, { api }) => {
          if ((event as PointerEvent).button === 0) api.startHold(event)
        },
        pointerup: (_event, { api }) => api.endHold(),
        pointerleave: (_event, { api }) => api.endHold(),
        pointercancel: (_event, { api }) => api.endHold(),
        focusout: (event, { api }) => {
          api.endHold()
          api.disarm("focus-out", event)
        },
      },
    }),
  }),
  agent: { actions: ["confirm"] },
})

export { confirmButton }
export type { ConfirmButtonArmedChangeReason, ConfirmButtonConfirmReason, ConfirmButtonOptions }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import type { ComponentProps, ReactNode } from "react"

import { buttonVariants } from "@/components/ui/button"
import {
  confirmButton,
  type ConfirmButtonArmedChangeReason,
  type ConfirmButtonConfirmReason,
  type ConfirmButtonOptions,
} from "@/components/ui/confirm-button-primitive"
import { Spinner } from "@/components/ui/spinner"
import { cn, cnState, mergeStyleVars } from "@/lib/utils"

const { Root: ConfirmButtonRoot } = createParts(confirmButton, { root: "button" })

type ConfirmButtonLabels = {
  /** The button's text and name while armed, and what a screen reader hears when it arms. */
  armed: string
  /** Describes a button with `hold`: a second press or a hold confirms. */
  holdHint: string
}

const confirmButtonLabels: ConfirmButtonLabels = {
  armed: "Press again to confirm",
  holdHint: "Press twice, or press and hold, to confirm",
}

type ConfirmButtonProps = Omit<ComponentProps<typeof ConfirmButtonRoot>, "children" | "armedAnnouncement"> & {
  /** What the button does, said to an agent's person before it runs: it becomes `data-agent-confirm`. */
  agentConfirm: string
  /** The idle content, which names the button. */
  children: ReactNode
  /** The content while armed. Defaults to `labels.armed`; it names the button then, so keep it text. */
  armedChildren?: ReactNode
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost"
  size?: "sm" | "default" | "lg"
  labels?: Partial<ConfirmButtonLabels>
}

const idleAndArmedInOneCell =
  "grid items-center justify-items-center *:col-start-1 *:row-start-1 *:inline-flex *:items-center *:gap-inline"

/**
 * The first press arms it (`data-armed`, its text becomes `labels.armed`), the second runs `onConfirm`. It disarms after `timeout`, on Escape or when focus leaves, each with its reason in `onArmedChange`.
 * With `hold`, holding it that long confirms too. Agents call `confirm`, which waits for a person through `allow`.
 */
function ConfirmButton({
  agentConfirm,
  children,
  armedChildren,
  variant = "destructive",
  size = "default",
  labels: ownLabels,
  hold,
  className,
  style,
  ...props
}: ConfirmButtonProps) {
  const labels = { ...confirmButtonLabels, ...ownLabels }
  return (
    <ConfirmButtonRoot
      data-agent-confirm={agentConfirm}
      hold={hold}
      armedAnnouncement={labels.armed}
      title={hold ? labels.holdHint : undefined}
      style={hold ? mergeStyleVars(style, { "--confirm-hold-duration": `${String(hold)}ms` }) : style}
      className={cnState(
        cn(
          buttonVariants({ variant, size }),
          "group/confirm relative overflow-hidden data-armed:bg-destructive data-armed:text-destructive-foreground data-armed:hover:bg-destructive/90",
        ),
        className,
      )}
      {...props}
    >
      {(state) => (
        <>
          {hold ? (
            <span
              aria-hidden
              className="pointer-events-none absolute inset-0 origin-left scale-x-0 bg-current opacity-20 group-data-holding/confirm:scale-x-100 group-data-holding/confirm:transition-transform group-data-holding/confirm:duration-(--confirm-hold-duration) group-data-holding/confirm:ease-linear rtl:origin-right"
            />
          ) : null}
          <span className={idleAndArmedInOneCell}>
            <span aria-hidden={state.armed || undefined} className={state.armed ? "invisible" : undefined}>
              {state.pending ? <Spinner size="sm" /> : null}
              {children}
            </span>
            <span aria-hidden={!state.armed || undefined} className={state.armed ? undefined : "invisible"}>
              {armedChildren ?? labels.armed}
            </span>
          </span>
        </>
      )}
    </ConfirmButtonRoot>
  )
}

export { ConfirmButton, confirmButtonLabels }
export type { ConfirmButtonLabels, ConfirmButtonProps }
export type { ConfirmButtonArmedChangeReason, ConfirmButtonConfirmReason, ConfirmButtonOptions }
